SELECT CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END AS started_cohort, AVG(we.duration_sec) AS avg_duration_sec, SUM(CASE WHEN we.event_type = 'click' THEN 1 ELSE 0 END) AS click_count FROM web_events we INNER JOIN sessions s ON we.session_id = s.id GROUP BY CASE WHEN YEAR(s.started_at) < 2024 THEN 'before_2024' WHEN YEAR(s.started_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(CASE WHEN we.event_type = 'click' THEN 1 ELSE 0 END) >= 74 ORDER BY avg_duration_sec DESC, started_cohort LIMIT 50
